(function(){'use strict';var form=document.getElementById('run-form');if(!form)return;var loadTools=document.getElementById('load-tools');var toolList=document.getElementById('tool-list');var toolRows=document.getElementById('tool-rows');var toolStatus=document.getElementById('tools-status');var toolKinds=Object.create(null);var runBtn=document.getElementById('run-btn');var cancelBtn=document.getElementById('cancel-btn');var statusEl=document.getElementById('run-status');var liveSec=document.getElementById('live');var phaseList=document.getElementById('phase-list');var resultSec=document.getElementById('result');var resultBody=document.getElementById('result-body');var openReport=document.getElementById('open-report');var downloadJSON=document.getElementById('download-json');var stream=null;var runID=null;var rows=Object.create(null);function val(id){var el=document.getElementById(id);return el?el.value.trim():'';}function checked(id){var el=document.getElementById(id);return!!(el&&el.checked);}function buildSpec(){var timeoutSec=parseFloat(val('timeout'))||30;return{target:{endpoint:val('endpoint')},credentials:{mode:val('auth')||'auto',token_env:val('token-env')||undefined},policy:{allow_mutations:checked('allow-mutations'),allow_destructive:checked('allow-destructive'),skip_era_check:checked('skip-era')},pacing:{rps:parseFloat(val('rps')),call_timeout_ns:Math.round(timeoutSec*1e9)},output:{format:'json'}};}function selectedTools(){var boxes=toolRows.querySelectorAll('input[type=checkbox]:checked');var names=[];for(var i=0;i<boxes.length;i++)names.push(boxes[i].value);return names;}function specWithSelection(){var spec=buildSpec();var names=selectedTools();if(!names.length)return spec;spec.policy.only=names;for(var i=0;i<names.length;i++){var kind=toolKinds[names[i]];if(kind==='mutating')spec.policy.allow_mutations=true;if(kind==='destructive')spec.policy.allow_destructive=true;}return spec;}function setStatus(text,kind){statusEl.textContent=text||'';statusEl.className='run-status'+(kind?''+kind:'');}function running(on){runBtn.disabled=on||!endpointLooksUsable();runBtn.textContent=on?'Running…':'Run diagnostic';cancelBtn.hidden=!on;}function endpointLooksUsable(){var v=val('endpoint');if(v==='')return false;try{var u=new URL(v);return u.protocol==='http:'||u.protocol==='https:';}catch(e){return false;}}function reflectEndpoint(){var ok=endpointLooksUsable();runBtn.disabled=!ok;if(ok){if(statusEl.textContent===''||/endpoint/i.test(statusEl.textContent))setStatus('');return;}setStatus(val('endpoint')===''?'Enter an endpoint to begin.':'That is not an http or https URL.');}function phaseRow(name){if(rows[name])return rows[name];var li=document.createElement('li');li.className='phase-row';li.setAttribute('data-phase',name);var status=document.createElement('span');status.className='status running';status.textContent='run';var label=document.createElement('span');label.className='phase-name';label.textContent=name;var summary=document.createElement('span');summary.className='phase-msg';var findings=document.createElement('ul');findings.className='phase-findings';li.appendChild(status);li.appendChild(label);li.appendChild(summary);li.appendChild(findings);phaseList.appendChild(li);rows[name]={li:li,status:status,summary:summary,findings:findings};return rows[name];}function addFinding(phase,f){if(!f||(f.status!=='fail'&&f.status!=='warn'))return;var row=phaseRow(phase);var li=document.createElement('li');li.className='finding-row';li.setAttribute('data-status',f.status);var chip=document.createElement('span');chip.className='status'+f.status;chip.textContent=f.status;var title=document.createElement('span');title.className='finding-title';title.textContent=f.title||f.id||'';var detail=document.createElement('span');detail.className='finding-detail';detail.textContent=f.detail||'';li.appendChild(chip);li.appendChild(title);li.appendChild(detail);row.findings.appendChild(li);}function finishPhase(result){if(!result)return;var row=phaseRow(result.name);row.status.className='status'+result.status;row.status.textContent=result.status;row.summary.textContent=result.summary||result.skipped||'';}function showResult(report){resultSec.hidden=false;resultBody.textContent='';var verdict=document.createElement('p');verdict.className='result-verdict';var counts=report.counts||{};if(report.blocked){verdict.textContent="Couldn't finish:"+report.blocked;verdict.setAttribute('data-kind','fail');}else if(counts.fail){verdict.textContent='Not ready for agents';verdict.setAttribute('data-kind','fail');}else if(counts.warn){verdict.textContent='Ready,with room to improve';verdict.setAttribute('data-kind','warn');}else{verdict.textContent='Ready for agents';verdict.setAttribute('data-kind','pass');}resultBody.appendChild(verdict);if(report.score&&report.score.categories_assessed){var score=document.createElement('p');score.className='result-score';score.textContent=Math.round(report.score.total)+'/100·'+(report.score.grade||'');resultBody.appendChild(score);}var tally=document.createElement('p');tally.className='field-help';tally.textContent=[counts.fail?counts.fail+'failed':'',counts.warn?counts.warn+'to improve':'',counts.pass?counts.pass+'passed':''].filter(Boolean).join('·');resultBody.appendChild(tally);openReport.href='runs/'+encodeURIComponent(runID)+'/report.html';downloadJSON.href='api/runs/'+encodeURIComponent(runID)+'/report.json';}function closeStream(){if(stream){stream.close();stream=null;}}function listen(id){stream=new EventSource('api/runs/'+encodeURIComponent(id)+'/events');stream.onmessage=function(ev){var e;try{e=JSON.parse(ev.data);}catch(err){return;}switch(e.type){case'phase_start':phaseRow(e.phase);break;case'finding':addFinding(e.phase,e.finding);break;case'phase_done':finishPhase(e.result);break;case'done':closeStream();running(false);if(e.error){setStatus(e.error,'fail');}else{setStatus('Finished','pass');}if(e.report)showResult(e.report);break;}};stream.onerror=function(){closeStream();running(false);setStatus('The connection to the run was lost.','fail');};}function renderTools(tools){toolRows.textContent='';toolKinds=Object.create(null);if(!tools||!tools.length){setToolStatus('This server lists no tools.','');toolList.hidden=true;return;}for(var i=0;i<tools.length;i++){var t=tools[i];toolKinds[t.name]=t.kind;var label=document.createElement('label');label.className='check';var box=document.createElement('input');box.type='checkbox';box.value=t.name;label.appendChild(box);var span=document.createElement('span');var strong=document.createElement('strong');strong.textContent=t.name;span.appendChild(strong);span.appendChild(document.createTextNode('\u2014'+t.kind+','+t.policy+(t.description?'.'+t.description:'')));label.appendChild(span);toolRows.appendChild(label);}toolList.hidden=false;setToolStatus(tools.length+(tools.length===1?'tool':'tools')+'listed.','');}function setToolStatus(text,kind){if(!toolStatus)return;toolStatus.textContent=text||'';toolStatus.className='run-status'+(kind?''+kind:'');}if(loadTools){loadTools.addEventListener('click',function(){if(!endpointLooksUsable()){setToolStatus('Enter an endpoint first.','fail');return;}loadTools.disabled=true;setToolStatus('Listing\u2026','');fetch('api/tools',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(buildSpec())}).then(function(r){return r.json().then(function(body){return{ok:r.ok,body:body};});}).then(function(res){loadTools.disabled=false;if(!res.ok){toolList.hidden=true;setToolStatus(res.body&&res.body.error?res.body.error:'The tools could not be listed.','fail');return;}renderTools(res.body.tools);}).catch(function(){loadTools.disabled=false;setToolStatus('passmcp is not reachable.Is it still running?','fail');});});}form.addEventListener('submit',function(ev){ev.preventDefault();var endpoint=val('endpoint');if(!endpoint){setStatus('Enter an endpoint to test.','fail');return;}rows=Object.create(null);phaseList.textContent='';resultSec.hidden=true;liveSec.hidden=false;running(true);setStatus('Starting…');fetch('api/runs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(specWithSelection())}).then(function(r){return r.json().then(function(body){return{ok:r.ok,body:body};});}).then(function(res){if(!res.ok){running(false);setStatus(res.body&&res.body.error?res.body.error:'The run could not be started.','fail');return;}runID=res.body.id;setStatus('Running');listen(runID);}).catch(function(){running(false);setStatus('passmcp is not reachable.Is it still running?','fail');});});var endpointEl=document.getElementById('endpoint');if(endpointEl){endpointEl.addEventListener('input',reflectEndpoint);reflectEndpoint();}cancelBtn.addEventListener('click',function(){if(!runID)return;fetch('api/runs/'+encodeURIComponent(runID),{method:'DELETE'}).catch(function(){});setStatus('Cancelling…');});})();